{
  "name": "@bangbang93/opencode-write-existing-file-guard",
  "version": "0.1.0",
  "description": "OpenCode plugin that blocks write to an existing file the session has not read",
  "type": "module",
  "license": "MIT",
  "keywords": [
    "opencode",
    "opencode-plugin",
    "write-existing-file-guard"
  ],
  "exports": {
    ".": "./index.ts"
  },
  "files": [
    "index.ts",
    "NOTICE.md"
  ],
  "publishConfig": {
    "access": "public"
  },
  "dependencies": {
    "@opencode/plugin": "^2.4.2"
  },
  "scripts": {
    "test": "node --test index.test.ts",
    "test:bun": "bun test",
    "typecheck": "tsc --noEmit -p tsconfig.json"
  }
}

import { existsSync, realpathSync } from "node:fs"
import { basename, dirname, isAbsolute, join, relative, resolve } from "node:path"
import { Plugin } from "@opencode/plugin"

const MAX_SESSIONS = 256
const MAX_PATHS_PER_SESSION = 1024

type FileInput = { path: string }

// realpathSync throws for a file that does not exist yet, so its directory is resolved instead.
function canonical(path: string): string {
  if (existsSync(path)) return realpathSync(path)
  const dir = dirname(path)
  return join(existsSync(dir) ? realpathSync(dir) : dir, basename(path))
}

function isInside(file: string, directory: string): boolean {
  const path = relative(directory, file)
  return path === "" || (!path.startsWith("..") && !isAbsolute(path))
}

export default Plugin.define({
  id: "write-existing-file-guard",
  async setup(ctx) {
    const root = canonical(ctx.location.directory)
    // Per session, the files a completed read lets it overwrite once. On both levels the least recently used entry comes first.
    const grants = new Map<string, Set<string>>()

    const fileOf = (input: FileInput) => canonical(resolve(ctx.location.directory, input.path))

    function touch(sessionID: string): Set<string> {
      const files = grants.get(sessionID) ?? new Set<string>()
      grants.delete(sessionID)
      grants.set(sessionID, files)
      return files
    }

    function grant(sessionID: string, file: string): void {
      if (grants.size === MAX_SESSIONS && !grants.has(sessionID)) grants.delete([...grants.keys()][0])
      const files = touch(sessionID)
      files.delete(file)
      files.add(file)
      if (files.size > MAX_PATHS_PER_SESSION) files.delete([...files][0])
    }

    function take(sessionID: string, file: string): boolean {
      if (!grants.get(sessionID)?.delete(file)) return false
      touch(sessionID)
      return true
    }

    function revokeReadsElsewhere(writer: string, file: string): void {
      for (const [sessionID, files] of grants) if (sessionID !== writer) files.delete(file)
    }

    await ctx.tool.hook("execute.before", async (event) => {
      if (event.tool !== "write") return
      const { path } = event.input as FileInput
      const file = fileOf({ path })
      if (!isInside(file, root) || !existsSync(file)) return
      if (!take(event.sessionID, file)) {
        throw new Error(`File already exists: ${path}. Read it with the read tool before you overwrite it.`)
      }
      revokeReadsElsewhere(event.sessionID, file)
    })

    await ctx.tool.hook("execute.after", async (event) => {
      if (event.status !== "completed" || event.tool !== "read") return
      const file = fileOf(event.input as FileInput)
      if (isInside(file, root)) grant(event.sessionID, file)
    })
  },
})
